import (
	Bytes from "@std/bytes.ms",
	panic from "@std/core.ms",
)

test "explicit byte conversion" {
	if not ("é".length() == 2) {
		return panic("check failed")
	}
	if not ("é".to_bytes().decode_utf8() == "é") {
		return panic("check failed")
	}

	invalid String? := null
	if not (Bytes([255]).decode_utf8() == invalid) {
		return panic("check failed")
	}
	if not ("-007".parse_int() == -7) {
		return panic("check failed")
	}
}
